.profileid ; CREATE OR REPLACE TABLE maplemonk.MedMongers_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED AS select o.*, cd.campaignname , adg.adgroupname , add.adname as ASIN , sm.brand, sm.commonsku, td.targeting_type , td.targeting_value, pd.profileName, PD.SELLERID, pd.ACCOUNTYPE from ( select ADVERTISER_ID ,MARKETPLACE_ID ,PROFILEID ,Date ,Hour ,\'SPONSORED BRANDS\' AD_TYPE_1 ,AD_ID ,KEYWORD_ID ,AD_GROUP_ID ,CAMPAIGN_ID ,null as target_id ,KEYWORD_TEXT ,KEYWORD_TYPE ,null as TARGETING_TEXT ,PLACEMENT_TYPE ,CURRENCY ,ATTRIBUTED_SALES_14D ,ATTRIBUTED_UNITS_ORDERED_14D ,ATTRIBUTED_CONVERSIONS_14D ,VIEW_ATTRIBUTED_SALES_14D ,VIEW_ATTRIBUTED_UNITS_ORDERED_14D ,VIEW_ATTRIBUTED_CONVERSIONS_14D ,ATTRIBUTED_SALES_14D_SAME_SKU ,ATTRIBUTED_CONVERSIONS_14D_SAME_SKU ,ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,SPEND ,IMPRESSIONS ,CLICKS ,VIEWABLE_IMPRESSIONS from maplemonk.MedMongers_AA_SB_CONSOLIDATED_HOURLY_DATA union all select ADVERTISER_ID ,MARKETPLACE_ID ,PROFILEID ,Date ,Hour ,\'SPONSORED DISPLAY\' AD_TYPE_1 ,AD_ID ,null as keyword_id ,AD_GROUP_ID ,CAMPAIGN_ID ,TARGET_ID ,null as keyword_text ,null as KEYWORD_TYPE ,TARGETING_TEXT ,null as PLACEMENT_TYPE ,CURRENCY ,ATTRIBUTED_SALES_14D ,ATTRIBUTED_UNITS_ORDERED_14D ,ATTRIBUTED_CONVERSIONS_14D ,VIEW_ATTRIBUTED_SALES_14D ,VIEW_ATTRIBUTED_UNITS_ORDERED_14D ,VIEW_ATTRIBUTED_CONVERSIONS_14D ,ATTRIBUTED_SALES_14D_SAME_SKU ,ATTRIBUTED_CONVERSIONS_14D_SAME_SKU ,ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,VIEW_ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,SPEND ,IMPRESSIONS ,CLICKS ,VIEWABLE_IMPRESSIONS from maplemonk.MedMongers_AA_SD_CONSOLIDATED_HOURLY_DATA union all select ADVERTISER_ID ,MARKETPLACE_ID ,PROFILEID ,Date ,Hour ,\'SPONSORED PRODUCT\' AD_TYPE_1 ,AD_ID ,KEYWORD_ID ,AD_GROUP_ID ,CAMPAIGN_ID ,null as target_id ,KEYWORD_TEXT ,MATCH_TYPE ,null as target_text ,PLACEMENT ,CURRENCY ,ATTRIBUTED_SALES_14D ,ATTRIBUTED_UNITS_ORDERED_14D ,ATTRIBUTED_CONVERSIONS_14D ,null as VIEW_ATTRIBUTED_SALES_14D ,null as VIEW_ATTRIBUTED_UNITS_ORDERED_14D ,null as VIEW_ATTRIBUTED_CONVERSIONS_14D ,ATTRIBUTED_SALES_14D_SAME_SKU ,ATTRIBUTED_CONVERSIONS_14D_SAME_SKU ,null as ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,null as ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,null as ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,null as VIEW_ATTRIBUTED_SALES_NEW_TO_BRAND_14D ,null as VIEW_ATTRIBUTED_UNITS_ORDERED_NEW_TO_BRAND_14D ,null as VIEW_ATTRIBUTED_ORDERS_NEW_TO_BRAND_14D ,SPEND ,IMPRESSIONS ,CLICKS ,null as VIEWABLE_IMPRESSIONS from maplemonk.MedMongers_AA_SP_CONSOLIDATED_HOURLY_DATA )as o left join maplemonk.MedMongers_amazon_ads_campaign_details cd on o.campaign_id = cd.campaignid left join maplemonk.MedMongers_amazon_ads_adgroup_details adg on o.campaign_id = adg.campaignid and o.AD_GROUP_ID = adg.adgroupid left join maplemonk.MedMongers_amazon_ads_ad_details add on o.campaign_id = add.campaignid and o.AD_GROUP_ID = add.adgroupid and o.ad_id = add.adid left join maplemonk.MedMongers_amazon_ads_targeting_details td on o.campaign_id = td.campaignid and o.AD_GROUP_ID = td.adgroupid and o.target_id = td.targetid left join maplemonk.MedMongers_amazon_ads_keyword_details kd on o.campaign_id = kd.campaignid and o.AD_GROUP_ID = kd.adgroupid and o.keyword_id = kd.keywordid left join maplemonk.MedMongers_amazon_ads_profile_details pd on cast(o.profileid as string) = cast(pd.profileid as string) left join (select product_id, brand, upper(sku_code) as commonsku, from medmongers_db.maplemonk.MEDMONGERS_FINAL_SKU_MASTER where final_marketplace = \'AMAZON\' qualify row_number() over (partition by lower(product_id) order by 1)=1 ) sm on lower(sm.product_id) = lower(add.adname) ;",
